"""Read-only summary of node workflow tables."""
import argparse
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import re
import sys


EVERY = re.compile(r"([1-9][0-9]*)([rsmhd])")
CODE = re.compile(r"[+-]?[0-9]+")
SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
REQUIRED = {"routines": {"name", "every", "last_time", "last_code"},
            "schedule": {"name", "at", "claimed"}}


def reject_constant(value):
    raise ValueError("non-finite JSON constant: " + value)


def read_table(node, table):
    path = node / "wf" / (table + ".json")
    if not path.exists() and not path.is_symlink():
        return [], []
    try:
        data = json.loads(path.read_text(encoding="utf-8"),
                          parse_constant=reject_constant)
    except (OSError, UnicodeError, ValueError):
        data = None
    if (not isinstance(data, dict) or data.get("contract") != "wf-table/1"
            or not isinstance(data.get("columns"), list)
            or not all(isinstance(x, str) for x in data["columns"])
            or not isinstance(data.get("rows"), list)):
        return [], [{"table": table, "row": None, "why": "bad_table"}]
    return data["rows"], []


def timestamp(value, now):
    stamp = datetime.fromisoformat(value)
    if stamp.tzinfo is None or stamp.utcoffset() is None:
        stamp = stamp.replace(tzinfo=now.tzinfo)
    return stamp


def routine(row, now):
    match = EVERY.fullmatch(row["every"])
    if match is None:
        raise ValueError("invalid interval")
    raw_time = row["last_time"]
    stamp = timestamp(raw_time, now) if raw_time else None
    raw_code = row["last_code"]
    if raw_code == "":
        code = None
    elif raw_code == "running":
        code = "running"
    elif CODE.fullmatch(raw_code):
        code = int(raw_code)
    else:
        raise ValueError("invalid exit code")
    next_time = None
    due = False
    if stamp is not None and match[2] != "r":
        next_stamp = stamp + timedelta(seconds=int(match[1]) * SECONDS[match[2]])
        next_time = next_stamp.astimezone(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")
        due = now >= next_stamp
    if code == "running":
        state = "running"
    elif stamp is None:
        state = "never"
    elif isinstance(code, int) and code != 0:
        state = "failed"
    else:
        state = "overdue" if due else "ok"
    return {"name": row["name"], "every": row["every"],
            "last_time": raw_time or None, "last_code": code,
            "state": state, "next": next_time}


def scheduled(row, now):
    at = timestamp(row["at"], now)
    state = "interrupted" if row["claimed"] else ("due" if at <= now else "pending")
    return {"name": row["name"], "at": row["at"], "state": state}


def summarize(node, now):
    result = {"v": 1, "routines": [], "schedule": [],
              "counts": {"routines": {key: 0 for key in
                          ("running", "never", "failed", "overdue", "ok")},
                         "schedule": {key: 0 for key in
                          ("interrupted", "due", "pending")}}, "bad": []}
    for table in ("routines", "schedule"):
        rows, errors = read_table(node, table)
        result["bad"].extend(errors)
        seen = set()
        for index, row in enumerate(rows):
            name = row.get("name") if isinstance(row, dict) else None
            if isinstance(name, str) and name:
                if name in seen:
                    result["bad"].append({"table": table, "row": index, "why": "dup_name"})
                    continue
                seen.add(name)
            try:
                if (not isinstance(row, dict) or not REQUIRED[table] <= row.keys()
                        or not all(isinstance(value, str) for value in row.values())
                        or not row["name"]):
                    raise ValueError("invalid row")
                item = routine(row, now) if table == "routines" else scheduled(row, now)
            except (ValueError, OverflowError, TypeError):
                result["bad"].append({"table": table, "row": index, "why": "bad_row"})
                continue
            result[table].append(item)
            result["counts"][table][item["state"]] += 1
        result[table].sort(key=lambda item: item["name"])
    result["bad"].sort(key=lambda item: (item["table"],
                                           -1 if item["row"] is None else item["row"],
                                           item["why"]))
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description="Summarize workflow tables without writes")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
        if now.tzinfo is None or now.utcoffset() is None:
            raise ValueError("timezone required")
    except ValueError:
        parser.error("--now must be a timezone-aware ISO timestamp")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=True,
                     separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
